fn cube_root(n: u8) -> u8 {
    // For u8 inputs (0..=255), the cube root is at most 6 because 7^3 = 343 > 255.
    let n16 = n as u16;

    let mut lo: u8 = 0;
    let mut hi: u8 = 6; // inclusive

    while lo < hi {
        // Upper mid to ensure progress when lo+1 == hi
        let mid: u8 = lo + (hi - lo + 1) / 2;

        let m = mid as u16;
        let cube_mid = m * m * m;

        if cube_mid <= n16 {
            lo = mid;
        } else {
            hi = mid - 1;
        }
    }

    // lo is the greatest r in [0,6] with r^3 <= n, hence also n < (r+1)^3.
    // And r <= n holds for all u8 n (including 0).
    lo
}